INSERT IGNORE INTO album_media(album_id,asset_id,sort)
SELECT #{albumId},a.asset_id,#{sort}
FROM media_asset a INNER JOIN album alb ON alb.album_id=#{albumId}
WHERE a.public_id=#{assetId} AND a.owner_user_id=#{userId}
  AND alb.user_id=#{userId} AND a.space_id=alb.space_id AND a.deleted_at IS NULL
